     $  0000D+00)*AMP( K,43)+(-1.000000000000000D+00)*AMP( K,45) +(-1.0000000000
     $  00000D+00)*AMP( K,46)+(-1.000000000000000D+00) *AMP( K,47)+(-1.000000000
