     $  0000000D+00)*AMP( K,96)+( -1.000000000000000D+00)*TMP_JAMP(42)+((0.00000
     $  0000000000D+00 ,1.000000000000000D+00))*TMP_JAMP(49)+((0.000000000000000
     $  D+00 ,1.000000000000000D+00))*TMP_JAMP(50)
        JAMP(2,1) = (-1.000000000000000D+00)*AMP( K,37)+( -1.00000000000
